  "summary": "Implement streaming JSONL parsing in replay_analyzer.py to count malformed lines and aggregate per-session turns and invalid outputs. The current stub returns empty results; replace it with logic that reads the file line‑by‑line, validates JSON, and updates counters accordingly.",
  "files": [
    {
      "path": "scripts/replay_analyzer.py",
      "content": "import json
from collections import defaultdict

def analyze(path: str) -> dict:
    malformed_lines = 0
    sessions = defaultdict(lambda: {"turns": 0, "invalid_output": 0})

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
                session_id = record.get("sessionId")
                if session_id is None:
                    raise ValueError("Missing sessionId")
                if record.get("type") == "agent.turn":
                    sessions[session_id]["turns"] += 1
                elif record.get("type") == "error" and record.get("code") == "invalid_output":
                    sessions[session_id]["invalid_output"] += 1
                # other types are ignored
            except (json.JSONDecodeError, ValueError):
                malformed_lines += 1

    # Convert defaultdict to regular dict for JSON‑serializable output
    sessions = {sid: stats for sid, stats in sessions.items()}
    return {
        "malformed_lines": malformed_lines,
        "sessions": sessions,
    }"
    }
  ]
